            {
                lock (this)
                {
                    if (provider != null) return provider;
                    var p = new DefaultFileProvider(Folder, SearchOption.AllDirectories, new VersionContainer(EGame.GAME_UE6_0), StringComparer.OrdinalIgnoreCase);
                    p.Initialize();
                    p.Mount();
